<template><section class="service-enrollments"><h4>Services &amp; providers</h4><p>Each service keeps its own agency, provider, and schedule. Adding a service keeps existing enrollments in place.</p><p v-if="error" role="alert">{{error}}</p><ul><li v-for="service in services" :key="service.id"><div><strong>{{service.label}}</strong><span>{{service.provider_name||'Provider not assigned'}}<template v-if="service.organization_name"> · {{service.organization_name}}</template></span><small v-if="!service.is_active">Former enrollment</small></div><button v-if="service.is_active" type="button" :disabled="busy" @click="archive(service)">End enrollment</button></li></ul><form @submit.prevent="save"><label>Service<select v-model="draft.serviceKind"><option value="counseling">Counseling</option><option value="tutoring">Tutoring</option><option value="coaching">Coaching</option><option value="consultation">Consultation</option></select></label><label>Display name<input v-model="draft.label" maxlength="150" placeholder="e.g. Reading tutoring" /></label><label>Assigned provider<select v-model="draft.providerUserId"><option :value="0">Not assigned yet</option><option v-for="provider in providers" :key="provider.id" :value="provider.id">{{provider.first_name}} {{provider.last_name}}</option></select></label><label>School / program<select v-model="draft.organizationId"><option :value="0">Agency service</option><option v-for="org in organizations" :key="org.organization_id" :value="org.organization_id">{{org.organization_name||org.name}}</option></select></label><button :disabled="busy" type="submit">{{busy?'Saving…':'Add service enrollment'}}</button></form></section></template>
<script setup>
import {ref,watch} from 'vue';import api from '../../services/api';
const props=defineProps({clientId:[Number,String],agencyId:[Number,String],organizations:{type:Array,default:()=>[]}});
const services=ref([]),providers=ref([]),error=ref(''),busy=ref(false),draft=ref({serviceKind:'counseling',label:'',providerUserId:0,organizationId:0});let seq=0;
async function load(){const own=++seq;services.value=[];providers.value=[];error.value='';if(!props.clientId||!props.agencyId)return;try{const [s,p]=await Promise.all([api.get(`/clients/${props.clientId}/service-enrollments`,{params:{agencyId:props.agencyId}}),api.get('/users',{params:{agencyId:props.agencyId}})]);if(own!==seq)return;services.value=s.data.services||[];providers.value=(Array.isArray(p.data)?p.data:p.data.users||[]).filter(u=>['provider','provider_plus','clinician','supervisor','intern','intern_plus','clinical_practice_assistant','admin','super_admin'].includes(u.role));}catch(e){if(own===seq)error.value=e.response?.data?.error?.message||'Services could not be loaded.';}}
async function save(){busy.value=true;error.value='';try{const {data}=await api.post(`/clients/${props.clientId}/service-enrollments`,{...draft.value,agencyId:Number(props.agencyId),label:draft.value.label||({counseling:'Counseling',tutoring:'Tutoring',coaching:'Coaching',consultation:'Consultation'}[draft.value.serviceKind])});services.value=data.services;}catch(e){error.value=e.response?.data?.error?.message||'Service could not be saved.';}finally{busy.value=false;}}
async function archive(service){if(!confirm(`End ${service.label} with ${service.provider_name||'this agency'}? Existing appointments and records are kept. Review future appointments separately.`))return;busy.value=true;try{const {data}=await api.delete(`/clients/${props.clientId}/service-enrollments/${service.id}`,{params:{agencyId:props.agencyId}});services.value=data.services;}catch(e){error.value=e.response?.data?.error?.message||'Enrollment could not be ended.';}finally{busy.value=false;}}
watch(()=>[props.clientId,props.agencyId],load,{immediate:true});
</script>
<style scoped>.service-enrollments{padding:20px;background:white;border:1px solid #dbe5ed;border-radius:14px;margin:16px 0}.service-enrollments p{font-size:13px;color:#52657a}.service-enrollments ul{list-style:none;padding:0}.service-enrollments li{display:flex;justify-content:space-between;gap:12px;padding:12px 0;border-bottom:1px solid #e3eaf1}.service-enrollments li span,.service-enrollments li small{display:block}.service-enrollments form{display:flex;flex-wrap:wrap;gap:14px;align-items:end}.service-enrollments label{display:flex;flex-direction:column;gap:6px;font-size:13px}.service-enrollments select,.service-enrollments input,.service-enrollments button{padding:9px;border:1px solid #c8d6e0;border-radius:8px;background:white;color:#23466b}</style>
